const MAX_WORDS:usize=32;const MAX_WORD_LEN:usize=8;const MAX_INPUT:usize=307;
fn eq(v:&[i64],s:usize,n:usize,t:usize,m:usize)->bool{n==m&&(0..n).all(|i|v[s+i]==v[t+i])}
#[no_mangle]
pub unsafe extern "C" fn shortest_word_distance(v:*const i64,length:usize)->i64{if v.is_null()||length<1||length>MAX_INPUT+1{return -1;}let a=core::slice::from_raw_parts(v,length);if !(2..=MAX_WORDS as i64).contains(&a[0]){return -1;}let n=a[0] as usize;let mut starts=[0usize;MAX_WORDS];let mut sizes=[0usize;MAX_WORDS];let mut p=1;for i in 0..n{if p>=length{return -1;}let z=a[p];p+=1;if !(1..=8).contains(&z)||p+z as usize>length{return -1;}starts[i]=p;sizes[i]=z as usize;if a[p..p+z as usize].iter().any(|&x|!((65..=90).contains(&x)||(97..=122).contains(&x))){return -1;}p+=z as usize;}let mut ts=[0usize;2];let mut tn=[0usize;2];for t in 0..2{if p>=length{return -1;}let z=a[p];p+=1;if !(1..=8).contains(&z)||p+z as usize>length{return -1;}ts[t]=p;tn[t]=z as usize;if a[p..p+z as usize].iter().any(|&x|!((65..=90).contains(&x)||(97..=122).contains(&x))){return -1;}p+=z as usize;}if p!=length||eq(a,ts[0],tn[0],ts[1],tn[1]){return -1;}let mut h0=false;let mut h1=false;let mut best=n;for i in 0..n{let x=eq(a,starts[i],sizes[i],ts[0],tn[0]);let y=eq(a,starts[i],sizes[i],ts[1],tn[1]);h0|=x;h1|=y;for j in 0..n{let c=eq(a,starts[j],sizes[j],ts[0],tn[0]);let d=eq(a,starts[j],sizes[j],ts[1],tn[1]);if(x&&d)||(y&&c){best=best.min(i.abs_diff(j));}}}if h0&&h1{best as i64}else{-1}}
